@@ -0,0 +1,62 @@
+# Reviewer-owned byte and evidence audit. Does not invoke received Python, tests or optimizers.
+$ErrorActionPreference='Stop'
+$rr=[IO.Path]::GetFullPath($PSScriptRoot)
+$cap=Get-Content -LiteralPath (Join-Path $rr 'CAPTURE_INDEX.json') -Raw | ConvertFrom-Json
+$records=@()
+foreach($c in $cap){
+  $p=Join-Path $rr $c.capture
+  $b=[IO.File]::ReadAllBytes($p)
+  $header=[Text.Encoding]::ASCII.GetBytes(('blob '+$b.Length+[char]0))
+  $all=[byte[]]::new($header.Length+$b.Length)
+  [Array]::Copy($header,0,$all,0,$header.Length)
+  [Array]::Copy($b,0,$all,$header.Length,$b.Length)
+  $alg=[Security.Cryptography.SHA1]::Create()
+  try{$actual=([BitConverter]::ToString($alg.ComputeHash($all))).Replace('-','').ToLowerInvariant()}finally{$alg.Dispose()}
+  if($actual -ne $c.git_blob){throw "Git blob mismatch: $($c.repo_path)"}
+  $records+=@{path=$c.repo_path;bytes=$b.Length;git_blob=$actual;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
+}
+$bms=Join-Path $rr 'source/bms-balancing'
+$intake='C:/Users/Administrator/Downloads/REIL_C4_0B1_FIX_RESULT_REVIEW_SEND_20261013.md'
+$intakeHash=(Get-FileHash -LiteralPath $intake -Algorithm SHA256).Hash.ToLowerInvariant()
+$send=$records | Where-Object path -eq 'bms-balancing/docs/REIL_C4_0B1_FIX_RESULT_REVIEW_SEND_20261013.md'
+if($intakeHash -ne $send.sha256){throw 'Attached request differs from frozen repository file'}
+$draft=$records | Where-Object path -eq 'bms-balancing/docs/REIL_C4_0B1_FIX_CONTROLS_DRAFT_20261013.py.txt'
+$test=$records | Where-Object path -eq 'bms-balancing/tests/test_reil_c4_0b1_fix.py'
+if($draft.sha256 -ne $test.sha256){throw 'Controls differ from preapproved draft'}
+$com=Get-Content -LiteralPath (Join-Path $rr 'COMMIT_d02e1507.json') -Raw | ConvertFrom-Json
+$committedCount=0
+foreach($f in $com.files){
+  $r=$records | Where-Object path -eq $f.filename
+  if($null -eq $r -or $r.git_blob -ne $f.sha){throw "Committed file not captured exactly: $($f.filename)"}
+  $committedCount++
+}
+$dirs=Get-Content -LiteralPath (Join-Path $rr 'DIRECTORY_IDENTITIES.json') -Raw | ConvertFrom-Json
+$prior=$dirs | Where-Object { $_.ref -like '7505bd00*' }
+$current=$dirs | Where-Object { $_.ref -like 'c6787db2*' }
+$preserved=@()
+foreach($d in $prior){
+  $now=$current | Where-Object path -eq $d.path
+  $selected=@($d.entries | Where-Object {$d.path -like '*/evidence/*' -or $_.name -like 'reil_c4_arrays*'})
+  foreach($e in $selected){
+    $n=$now.entries | Where-Object path -eq $e.path
+    if($null -eq $n -or $n.sha -ne $e.sha){throw "Preservation mismatch: $($e.path)"}
+    $preserved+=@{path=$e.path;git_object=$e.sha;type=$e.type}
+  }
+}
+$ev=Join-Path $bms 'evidence/reil_c4_0b1_fix_20261013'
+$steps=@('01_identity','02_red','03_green') | ForEach-Object {Get-Content -LiteralPath (Join-Path $ev ($_+'.meta.json')) -Raw | ConvertFrom-Json}
+$total=($steps | Measure-Object elapsed_s -Sum).Sum
+$green=Get-Content -LiteralPath (Join-Path $ev '03_green.stdout.log') -Raw
+$red=Get-Content -LiteralPath (Join-Path $ev '02_red.stdout.log') -Raw
+if($green -notmatch '66 passed' -or $red -notmatch '10 failed, 5 passed'){throw 'Test summary mismatch'}
+$out=[ordered]@{
+  kind='READ_ONLY_REVIEWER_EVIDENCE_AUDIT';reviewed_ref='c6787db21c6608d3b5ad57fe7e39dfa865b5d6da'
+  captured_files=$records.Count;captured_git_blobs_all_match=$true;production_commit_members=$committedCount
+  request_attachment_sha256=$intakeHash;request_attachment_matches=$true;controls_match_prefixed_draft=$true
+  preserved_git_objects=$preserved;producer_step_seconds=$total
+  steps=@($steps | Select-Object step,rc,elapsed_s,timeout_s,head_start,head_end,timed_out)
+  records=$records
+  limitations=@('Producer logs inspected, not independently rerun.','Git object equality is fixed-commit preservation, not continuous machine observation.','129.1 seconds is precommit work snapshot, not final overall elapsed.')
+  received_code_or_test_execution=0;data_opened=0;new_execution_approval=$false
+}
+$out | ConvertTo-Json -Depth 20

@@ -0,0 +1,81 @@
+# Reviewer-owned packaging only. Never imports or invokes received code/tests.
+$ErrorActionPreference = 'Stop'
+$reviewRoot = [IO.Path]::GetFullPath($PSScriptRoot)
+$zipName = 'REIL_C4_0B1_FIX_RESULT_REVIEW_20261014.zip'
+$zipPath = Join-Path $reviewRoot $zipName
+$manifestPath = Join-Path $reviewRoot 'PACKAGE_MANIFEST.json'
+$receiptPath = Join-Path $reviewRoot 'DELIVERY_RECEIPT.json'
+foreach ($p in @($zipPath,$manifestPath,$receiptPath)) {
+    if (Test-Path -LiteralPath $p) { throw "Refuse overwrite: $p" }
+}
+function Save-NewJson($path,$value) {
+    $text = ($value | ConvertTo-Json -Depth 40) + "`n"
+    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
+    $stream = [IO.File]::Open($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
+    try { $stream.Write($bytes,0,$bytes.Length) } finally { $stream.Dispose() }
+}
+function Digest-Bytes($bytes) {
+    $sha = [Security.Cryptography.SHA256]::Create()
+    try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() }
+    finally { $sha.Dispose() }
+}
+$index = Get-Content -LiteralPath (Join-Path $reviewRoot 'CAPTURE_INDEX.json') -Raw | ConvertFrom-Json
+foreach ($item in $index) {
+    $bytes = [IO.File]::ReadAllBytes((Join-Path $reviewRoot $item.capture))
+    $header = [Text.Encoding]::ASCII.GetBytes(('blob '+$bytes.Length+[char]0))
+    $both = [byte[]]::new($header.Length+$bytes.Length)
+    [Array]::Copy($header,0,$both,0,$header.Length)
+    [Array]::Copy($bytes,0,$both,$header.Length,$bytes.Length)
+    $sha = [Security.Cryptography.SHA1]::Create()
+    try { $blob = ([BitConverter]::ToString($sha.ComputeHash($both))).Replace('-','').ToLowerInvariant() }
+    finally { $sha.Dispose() }
+    if ($blob -ne $item.git_blob) { throw "Captured Git blob mismatch: $($item.capture)" }
+}
+$files = @(Get-ChildItem -LiteralPath $reviewRoot -Recurse -File | Sort-Object FullName)
+$members = @()
+$seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
+foreach ($f in $files) {
+    $relative = $f.FullName.Substring($reviewRoot.Length+1).Replace('\','/')
+    if (-not $seen.Add($relative)) { throw 'Case-insensitive duplicate path' }
+    if (($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Reparse point refused' }
+    $members += [ordered]@{path=$relative;bytes=$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}
+    if ($f.Extension -eq '.json') { $null = Get-Content -LiteralPath $f.FullName -Raw | ConvertFrom-Json }
+}
+$manifest = [ordered]@{kind='REVIEW_PACKAGE_MANIFEST';members=$members;self_excluded=$true;scope='Review evidence, not executable authorization'}
+Save-NewJson $manifestPath $manifest
+Add-Type -AssemblyName System.IO.Compression
+Add-Type -AssemblyName System.IO.Compression.FileSystem
+$archive = [IO.Compression.ZipFile]::Open($zipPath,[IO.Compression.ZipArchiveMode]::Create)
+try {
+    foreach ($m in $members) {
+        $null = [IO.Compression.ZipFileExtensions]::CreateEntryFromFile($archive,(Join-Path $reviewRoot $m.path),$m.path,[IO.Compression.CompressionLevel]::Optimal)
+    }
+    $null = [IO.Compression.ZipFileExtensions]::CreateEntryFromFile($archive,$manifestPath,'PACKAGE_MANIFEST.json',[IO.Compression.CompressionLevel]::Optimal)
+} finally { $archive.Dispose() }
+$expected = @{}
+foreach ($m in $members) { $expected[$m.path]=$m }
+$expected['PACKAGE_MANIFEST.json']=@{path='PACKAGE_MANIFEST.json';bytes=(Get-Item -LiteralPath $manifestPath).Length;sha256=(Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant()}
+$archive = [IO.Compression.ZipFile]::OpenRead($zipPath)
+try {
+    if ($archive.Entries.Count -ne $expected.Count) { throw 'ZIP entry count mismatch' }
+    $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
+    foreach ($e in $archive.Entries) {
+        if (-not $seen.Add($e.FullName) -or -not $expected.ContainsKey($e.FullName)) { throw 'ZIP name mismatch' }
+        $inputStream=$e.Open(); $buffer=[IO.MemoryStream]::new()
+        try { $inputStream.CopyTo($buffer);$raw=$buffer.ToArray() } finally { $inputStream.Dispose();$buffer.Dispose() }
+        $m=$expected[$e.FullName]
+        if ($raw.Length -ne $m.bytes -or (Digest-Bytes $raw) -ne $m.sha256) { throw "ZIP bytes mismatch: $($e.FullName)" }
+    }
+} finally { $archive.Dispose() }
+$receipt = [ordered]@{
+    kind='REVIEW_DELIVERY_RECEIPT';recipient=$null
+    decision='C4_0B1_IMPLEMENTATION_CLOSURE_HELD_N1_REMAINDER'
+    reviewed_ref='c6787db21c6608d3b5ad57fe7e39dfa865b5d6da'
+    archive=@{file=$zipName;bytes=(Get-Item -LiteralPath $zipPath).Length;sha256=(Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash.ToLowerInvariant()}
+    manifest=@{bytes=(Get-Item -LiteralPath $manifestPath).Length;sha256=(Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant()}
+    payload_count=$members.Count;zip_entries=$expected.Count;capture_git_blob_matches=$index.Count
+    verification='Exact member set, sizes and decompressed SHA256 matched; CRC not separately recomputed.'
+    received_code_or_test_execution=0;new_execution_approval=$false;external_delivery_performed=$false
+}
+Save-NewJson $receiptPath $receipt
+$receipt | ConvertTo-Json -Depth 15
